                m[0][1], m[1][1], m[2][1], 0.0,
                m[0][2], m[1][2], m[2][2], 0.0,
                -dot(m[0].xyz,m[3].xyz),
                -dot(m[1].xyz,m[3].xyz),
                -dot(m[2].xyz,m[3].xyz),
                1.0 );
        }

        void amzVertex_main() {
            vertShaderInit();
            invOrient = (amzQuaternion(amzp_orient*float4(-1,-1,-1,1)));
        }



        float sdTriPrism( float3 p, float2 h )
