        float directionalLighting(float3 p, float3 n) {
            float3 lightPos = float3(amzp_lightDir.x/2.0, -amzp_lightDir.y/2.0, -amzp_lightDepth*2.0);
            float3 l = normalize(lightPos);
            return dot(n,l);
        }
